#!/usr/bin/env python3
"""Writes the "bytes" region of crypto/PROOF_ctr.bend.

  python3 gen/ctr_proof.py           rewrite the region between the lines
                                     "# BEGIN GENERATED by gen/ctr_proof.py: bytes"
                                     and "# END GENERATED: bytes"
  python3 gen/ctr_proof.py --check   only check that it is up to date

The region holds two facts about one byte, each checked on all 256 values
of its eight bits (the byte as bytes.bend's oct.to makes it, the high 24
bits zero): ct.e1, adding one to a byte with its carry (the byte b + 1, and
a carry of 256 exactly when b is 255) is adding one; and ct.e2, a byte's
value is at most 255. Everything outside the region is written by hand.
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PROOF = os.path.join(HERE, "..", "PROOF_ctr.bend")

X8 = "U32{" + "".join("WCon{c%d, " % i for i in range(8)) + "Word.zero(24n)" + "}" * 8 + "}"
PARAMS = ", ".join("c%d: Bool" % i for i in range(8))
NAMES = " ".join("c%d" % i for i in range(8))


def cases():
    out = []
    for v in range(256):
        pat = " ".join("True{}" if (v >> i) & 1 else "False{}" for i in range(8))
        out.append("    case %s:\n      {==}\n" % pat)
    return "".join(out)


def region():
    e1 = ("# one added to the byte of bits c0 (least significant) .. c7, with its carry\n"
          "def ct.e1(%s) -> {Nat.add(U32.to_nat(B.byte(U32.add(%s, 1))), Nat.mul(ct.b2n(U32.is_eq(%s, 255)), 256n)) == Nat.add(U32.to_nat(%s), 1n) : Nat}:\n"
          "  match %s:\n%s") % (PARAMS, X8, X8, X8, NAMES, cases())
    e2 = ("# the byte's value is at most 255\n"
          "def ct.e2(%s) -> {Nat.is_le(U32.to_nat(%s), 255n) == True{} : Bool}:\n"
          "  match %s:\n%s") % (PARAMS, X8, NAMES, cases())
    return e1 + "\n" + e2


def main():
    check = "--check" in sys.argv[1:]
    with open(PROOF) as f:
        text = f.read()
    begin = "# BEGIN GENERATED by gen/ctr_proof.py: bytes\n"
    end = "# END GENERATED: bytes\n"
    i, j = text.index(begin) + len(begin), text.index(end)
    new = text[:i] + region() + text[j:]
    if check:
        if new != text:
            print("PROOF_ctr.bend: region bytes is out of date (run gen/ctr_proof.py)")
            sys.exit(1)
        print("PROOF_ctr.bend: up to date")
        return
    with open(PROOF, "w", newline="\n") as f:
        f.write(new)


if __name__ == "__main__":
    main()
